struct BaseTable64 {
	std::uint16_t values[16384]{};
	constexpr BaseTable64(const char *s) {
		auto digit = [](char c) { return c - '0' - (c > '?') - (c > '\\'); };
		for (unsigned i = 0; i < 16384; ++i)
			values[i] = std::uint16_t((digit(s[3 * i]) << 12) | (digit(s[3 * i + 1]) << 6) | digit(s[3 * i + 2]));
	}
};
